// Data access layer. The UI only talks to a DataSource, never to fetch() directly.
//
// Today: StaticJsonSource reads the JSON files regenerated by the daily ingestion
// job, and polls meta.json so an open tab picks up a new run without reload.
// Tomorrow: swap in an API-backed source (same `load()` / `subscribe()` contract)
// or set config.LIVE_STREAM_URL to push updates over Server-Sent Events.

import { config } from '../config.mjs';

const DATASETS = ['opportunities', 'cohesion', 'instruments'];

export class StaticJsonSource {
  constructor({ base = config.DATA_BASE, pollMs = config.POLL_INTERVAL_MS, streamUrl = config.LIVE_STREAM_URL } = {}) {
    this.base = base;
    this.pollMs = pollMs;
    this.streamUrl = streamUrl;
    this.listeners = new Set();
    this.snapshot = null;
    this.timer = null;
    this.stream = null;
  }

  async #get(name, version) {
    const url = new URL(`${name}.json`, this.base);
    if (version) url.searchParams.set('v', version);
    const res = await fetch(url, { cache: version ? 'default' : 'no-store' });
    if (!res.ok) throw new Error(`Impossible de charger ${name}.json (HTTP ${res.status})`);
    return res.json();
  }

  /** Load every dataset, versioned by meta.generatedAt so browser caches stay coherent. */
  async load() {
    const meta = await this.#get('meta');
    const version = meta.generatedAt;
    const entries = await Promise.all(DATASETS.map(async (d) => [d, await this.#get(d, version)]));
    const data = Object.fromEntries(entries);
    this.snapshot = {
      meta,
      opportunities: data.opportunities.items || [],
      cohesion: data.cohesion.items || [],
      instruments: data.instruments.items || [],
    };
    return this.snapshot;
  }

  /** Notified with (snapshot, previousSnapshot) whenever a newer dataset is published. */
  subscribe(fn) {
    this.listeners.add(fn);
    this.#start();
    return () => this.listeners.delete(fn);
  }

  async refreshIfNewer(knownVersion) {
    const meta = await this.#get('meta');
    if (!this.snapshot || meta.generatedAt === (knownVersion ?? this.snapshot.meta.generatedAt)) return false;
    const previous = this.snapshot;
    await this.load();
    for (const fn of this.listeners) fn(this.snapshot, previous);
    return true;
  }

  #start() {
    if (this.streamUrl && 'EventSource' in window && !this.stream) {
      this.stream = new EventSource(this.streamUrl);
      this.stream.addEventListener('message', (e) => {
        try {
          const msg = JSON.parse(e.data);
          if (msg.type === 'update') this.refreshIfNewer().catch(() => {});
        } catch { /* ignore malformed events */ }
      });
      return;
    }
    if (!this.pollMs || this.timer) return;
    const tick = () => {
      if (document.visibilityState === 'visible') this.refreshIfNewer().catch(() => {});
    };
    this.timer = setInterval(tick, this.pollMs);
    document.addEventListener('visibilitychange', tick);
  }
}
